def ordinal(n):
    """1 -> '1st', 2 -> '2nd', 3 -> '3rd', 4 -> '4th'; teens are 'th'
    (11th, 12th, 13th, 112th) while 21/22/23 etc. follow the digit rule
    (21st, 121st). Negative n raises ValueError."""
    if n < 0:
        raise ValueError(f"n must be >= 0: {n}")
    if 10 <= n % 100 <= 13:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"

